// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        vm.deal(actor, amount * 2);

        bool ok1;
        vm.prank(actor);
        try c.Put{value: amount}(0) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        if (!ok1) return; // first deposit must succeed in the reference; skip otherwise

        bool ok2;
        vm.prank(actor);
        try c.Put{value: amount}(0) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // General rule: the reentrancy lock is always released after a completed
        // Put, so any subsequent Put from any account succeeds.
        assertTrue(ok2);
    }
}
